const fs = require('fs');
const path = 'src/worker.js';
const src = fs.readFileSync(path, 'utf8');
const backup = path + '.bak-provider-ui-20261015';
if (!fs.existsSync(backup)) fs.copyFileSync(path, backup);
let out = src;
const panel = /<details class=card style=margin-top:16px><summary style="cursor:pointer;font-weight:700">WhatsBox Delivery & Test Status<\/summary>.*?<\/details><div class=card style=margin-top:16px><h3>AI Automation Controls - ON \/ OFF<\/h3>/s;
const replacement = '<details class=card style=margin-top:16px><summary style="cursor:pointer;font-weight:700">Partner Delivery & Provider Status</summary><div style="padding-top:12px"><h3>Active partner notification route</h3><p><b>Current route:</b> Owner-approved partner email through the existing Gmail provider, with notification drafts retained in the PakThai Tech dashboard queue.</p><p>This route does not require Meta/WhatsApp phone verification. Automated WhatsApp/Meta API sending is paused and is not used by this delivery route. Historical WhatsBox records are retained; this panel will not call Meta diagnostics or request verification codes.</p><p><b>Delivery proof:</b> Gmail provider acceptance alone does not confirm that a message reached the recipient inbox. Check the provider/mailbox for delivery or bounce evidence before marking a partner reached.</p><p><b>Not active yet:</b> Resend sender credentials/domain verification and browser push/FCM configuration are absent. They must not be treated as working backup channels.</p><p>To deliver a partner notification, open Outgoing Message Queue, review the draft and use the Owner-approved email action. No external message is sent automatically.</p><button class="alt" onclick="loadOutboundQueue()">Refresh Message Queue</button></div></details><div class=card style=margin-top:16px><h3>AI Automation Controls - ON / OFF</h3>';
const matches = out.match(panel) || [];
if (matches.length !== 1) throw new Error('Expected exactly one legacy WhatsBox status panel; found ' + matches.length + '. No patch applied.');
out = out.replace(panel, replacement);
const mailboxSig = "async function loadWhatsAppMailbox(){";
if ((out.match(new RegExp(mailboxSig.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g')) || []).length !== 1) throw new Error('Expected one loadWhatsAppMailbox function.');
out = out.replace(mailboxSig, "async function loadWhatsAppMailbox(){const box=document.getElementById('whatsAppMailbox');if(box){box.textContent='Legacy WhatsApp inbox is paused during provider migration. No Meta API diagnostics are run from this dashboard. Use the Owner-approved partner email queue; historical records remain stored.';}return;");
const statusSig = "async function loadWhatsAppStatus(){";
if ((out.match(new RegExp(statusSig.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g')) || []).length !== 1) throw new Error('Expected one loadWhatsAppStatus function.');
out = out.replace(statusSig, "async function loadWhatsAppStatus(){const summary=document.getElementById('whatsappDeliverySummary');const hook=document.getElementById('whatsappWebhookSetup');const list=document.getElementById('whatsappDeliveryList');if(summary)summary.textContent='Meta/WhatsApp automated delivery is paused; use the active email queue instead.';if(hook)hook.textContent='No Meta diagnostics are requested from this panel.';if(list)list.textContent='Historical WhatsApp delivery records are retained but not refreshed from Meta.';return;");
fs.writeFileSync(path, out, 'utf8');
console.log('PATCH_OK: backed up ' + backup + '; replaced stale Meta verification panel; dashboard WhatsBox refreshes now fail closed without Meta API calls.');
